+const groundGeo=new THREE.CircleGeometry(78,100);const pos=groundGeo.attributes.position;const colors=[];const grassA=new THREE.Color('#4c916b'),grassB=new THREE.Color('#75a96e'),sand=new THREE.Color('#c1a56f');for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getY(i),r=Math.hypot(x,z);const noise=Math.sin(x*.23)*Math.cos(z*.18)*.65+Math.sin(z*.39+x*.09)*.35;let h=Math.max(0,1-r/80);pos.setZ(i,Math.max(-.3, h*(noise+1)*1.8));let c=r>69?sand.clone().lerp(grassA,Math.max(0,Math.min(1,(76-r)/7))):grassA.clone().lerp(grassB,Math.max(0,Math.min(1,(noise+.4)*.5)));colors.push(c.r,c.g,c.b)}groundGeo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));groundGeo.computeVertexNormals();const land=new THREE.Mesh(groundGeo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));land.rotation.x=-Math.PI/2;land.receiveShadow=true;scene.add(land);
