+function humanoid(isPlayer=false,color){const root=new THREE.Group(),body=new THREE.Group();root.add(body);const shirt=isPlayer?charMats.player:color;const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.43,.64,4,8),shirt);torso.position.y=1.48;torso.castShadow=true;body.add(torso);const head=new THREE.Mesh(new THREE.SphereGeometry(.31,10,8),charMats.skin);head.position.y=2.35;head.castShadow=true;body.add(head);for(const s of [-1,1]){const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.17,.62,3,6),charMats.pants);leg.position.set(s*.22,.54,0);leg.castShadow=true;body.add(leg);const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.13,.5,3,6),shirt);arm.position.set(s*.49,1.55,-.03);arm.rotation.z=s*.13;arm.castShadow=true;body.add(arm)}const pack=new THREE.Mesh(new THREE.BoxGeometry(.52,.58,.23),mat(isPlayer?'#607c55':'#5b5148'));pack.position.set(0,1.65,.39);body.add(pack);const gun=new THREE.Group();const barrel=new THREE.Mesh(new THREE.BoxGeometry(.13,.14,.95),charMats.gun);barrel.position.set(0,0,-.4);gun.add(barrel);const stock=new THREE.Mesh(new THREE.BoxGeometry(.18,.22,.35),charMats.dark);stock.position.z=.15;gun.add(stock);gun.position.set(.35,1.48,-.2);body.add(gun);const shadow=new THREE.Mesh(new THREE.CircleGeometry(.62,20),new THREE.MeshBasicMaterial({color:0x102218,transparent:true,opacity:.26,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.035;root.add(shadow);return {root,body,gun,legs:body.children.filter(o=>o.geometry?.type==='CapsuleGeometry'),health:100,isPlayer}};
