pickup('med',-5,16);pickup('weapon',25,8,weapons[1]);
let started=false,ended=false,elapsed=0,kills=0,health=100,weapon={name:'SERVICE RIFLE',damage:31,rate:.38,color:0xbde9d6},fireCooldown=0,viewYaw=0,moveX=0,moveZ=0,runHeld=false,fireHeld=false,mouseHeld=false,gameTime=0,toastTimer=0;const keys={},tracers=[];const clock=new THREE.Clock();
function showToast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');toastTimer=1.6}
function nearestTarget(max=34){let best=null,bd=max;for(const e of enemies){if(!e.alive)continue;const d=e.root.position.distanceTo(player.root.position);if(d<bd){bd=d;best=e}}return best}
function makeTracer(from,to,color=0x9cffbe){const points=[from.clone(),to.clone()],geo=new THREE.BufferGeometry().setFromPoints(points),line=new THREE.Line(geo,new THREE.LineBasicMaterial({color,transparent:true,opacity:.95}));scene.add(line);tracers.push({line,life:.12,max:.12})}
function fireShot(){if(fireCooldown>0||!started||ended)return;fireCooldown=weapon.rate;const target=nearestTarget(38);const start=player.root.localToWorld(new THREE.Vector3(.35,1.52,-.65));if(target){const end=target.root.position.clone().add(new THREE.Vector3(0,1.45,0));makeTracer(start,end,0xb7ffe0);target.health-=weapon.damage;if(target.health<=0){target.alive=false;scene.remove(target.root);kills++;$('#kills').textContent=String(kills).padStart(2,'0');if(Math.random()<.58)pickup(Math.random()<.45?'med':'weapon',target.root.position.x,target.root.position.z,weapons[Math.floor(Math.random()*weapons.length)]);showToast(`${target.name.toUpperCase()} ELIMINATED`)}else{target.root.userData.hitFlash=.14}}else{const dir=new THREE.Vector3(-Math.sin(player.root.rotation.y),.04,-Math.cos(player.root.rotation.y));makeTracer(start,start.clone().add(dir.multiplyScalar(24)),0xc5fff2)}}
function updateAlive(){const n=enemies.filter(e=>e.alive).length+1;$('#alive').textContent=String(n)}
function playerDamage(amount){if(ended)return;health=Math.max(0,health-amount);$('#healthNum').textContent=Math.ceil(health);$('#healthBar').style.width=health+'%';if(health<=0)finish(false)}
function finish(win){if(ended)return;ended=true;document.exitPointerLock?.();$('#endScreen').classList.remove('hide');$('#endTitle').innerHTML=win?'ISLAND<br><em>OUTLASTED.</em>':'ELIMINATED';$('#endEyebrow').textContent=win?'THE ISLAND REMEMBERS':'BETTER LUCK NEXT DROP';$('#endCopy').textContent=win?'Every rival down. You are the last light.':'The island claimed another. Drop back in and try again.';$('#finalKills').textContent=String(kills).padStart(2,'0');const t=Math.floor(gameTime);$('#finalTime').textContent=`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`}
function startGame(){started=true;$('#startScreen').classList.add('hide');$('#hud').style.display='block';clock.getDelta();if(innerWidth>750)renderer.domElement.requestPointerLock?.()}
$('#startBtn').addEventListener('click',startGame);$('#againBtn').addEventListener('click',()=>location.reload());
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault()});window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>{mouseHeld=false;fireHeld=false;runHeld=false});
renderer.domElement.addEventListener('mousedown',e=>{if(e.button===0){mouseHeld=true;if(started&&document.pointerLockElement!==renderer.domElement&&innerWidth>750)renderer.domElement.requestPointerLock?.()}});window.addEventListener('mouseup',e=>{if(e.button===0)mouseHeld=false});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer.domElement)viewYaw-=e.movementX*.0026});
const stickArea=$('#stickArea'),stick=$('#stick');let stickId=null;stickArea.addEventListener('pointerdown',e=>{stickId=e.pointerId;stickArea.setPointerCapture(stickId);moveStick(e)});stickArea.addEventListener('pointermove',e=>{if(e.pointerId===stickId)moveStick(e)});function moveStick(e){const r=stickArea.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),d=Math.min(44,Math.hypot(dx,dy)),a=Math.atan2(dy,dx);moveX=Math.cos(a)*d/44;moveZ=Math.sin(a)*d/44;stick.style.left=`calc(50% + ${moveX*33}px)`;stick.style.top=`calc(50% + ${moveZ*33}px)`}function endStick(e){if(e.pointerId!==stickId)return;stickId=null;moveX=moveZ=0;stick.style.left='50%';stick.style.top='50%'}stickArea.addEventListener('pointerup',endStick);stickArea.addEventListener('pointercancel',endStick);
$('#fireBtn').addEventListener('pointerdown',e=>{e.preventDefault();fireHeld=true});$('#fireBtn').addEventListener('pointerup',()=>fireHeld=false);$('#fireBtn').addEventListener('pointercancel',()=>fireHeld=false);$('#runBtn').addEventListener('pointerdown',e=>{e.preventDefault();runHeld=true;$('#runBtn').classList.add('active')});$('#runBtn').addEventListener('pointerup',()=>{runHeld=false;$('#runBtn').classList.remove('active')});$('#runBtn').addEventListener('pointercancel',()=>{runHeld=false;$('#runBtn').classList.remove('active')});
function updateCamera(dt){const p=player.root.position;const distance=innerWidth<700?8.7:8.1;const desired=new THREE.Vector3(p.x+Math.sin(viewYaw)*distance,p.y+5.25,p.z+Math.cos(viewYaw)*distance);camera.position.lerp(desired,1-Math.exp(-dt*5.5));camera.lookAt(p.x,p.y+1.25,p.z)}
function moveActor(actor,dir,speed,dt){if(dir.lengthSq()<.001)return;dir.normalize();actor.root.position.x+=dir.x*speed*dt;actor.root.position.z+=dir.z*speed*dt;const lim=75,d=Math.hypot(actor.root.position.x,actor.root.position.z);if(d>lim){actor.root.position.x*=lim/d;actor.root.position.z*=lim/d}actor.root.position.y=terrainY(actor.root.position.x,actor.root.position.z);actor.root.rotation.y=Math.atan2(-dir.x,-dir.z)}
function updatePlayer(dt){let ix=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+moveX,iz=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+moveZ;ix=Math.max(-1,Math.min(1,ix));iz=Math.max(-1,Math.min(1,iz));const f=new THREE.Vector3(-Math.sin(viewYaw),0,-Math.cos(viewYaw)),r=new THREE.Vector3(Math.cos(viewYaw),0,-Math.sin(viewYaw));const dir=f.multiplyScalar(-iz).add(r.multiplyScalar(ix));const moving=dir.lengthSq()>.02;let target=nearestTarget(35);if(target){const dx=target.root.position.x-player.root.position.x,dz=target.root.position.z-player.root.position.z;const ty=Math.atan2(-dx,-dz);let delta=((ty-viewYaw+Math.PI*3)%(Math.PI*2))-Math.PI;viewYaw+=delta*Math.min(1,dt*2.6);player.root.rotation.y+=((((ty-player.root.rotation.y+Math.PI*3)%(Math.PI*2))-Math.PI)*Math.min(1,dt*9))}else if(moving){const yaw=Math.atan2(-dir.x,-dir.z);player.root.rotation.y+=((((yaw-player.root.rotation.y+Math.PI*3)%(Math.PI*2))-Math.PI)*Math.min(1,dt*12))}if(moving){moveActor(player,dir,runHeld||keys.ShiftLeft||keys.ShiftRight?7.3:4.7,dt);player.root.rotation.y=target?player.root.rotation.y:Math.atan2(-dir.x,-dir.z)}player.body.position.y=moving?Math.abs(Math.sin(gameTime*11))*.06:0;player.legs.forEach((l,i)=>{if(i<2)l.rotation.x=moving?Math.sin(gameTime*11+i*Math.PI)*.45:0});if(mouseHeld||fireHeld)fireShot();fireCooldown=Math.max(0,fireCooldown-dt)}
function updateEnemies(dt){for(const e of enemies){if(!e.alive)continue;e.aiTimer-=dt;e.fireTimer-=dt;let target=e.target;if(e.aiTimer<=0||!target?.alive){let candidates=[player,...enemies].filter(x=>x!==e&&x.alive);candidates.sort((a,b)=>a.root.position.distanceToSquared(e.root.position)-b.root.position.distanceToSquared(e.root.position));target=candidates[0];e.target=target;e.aiTimer=1.1+Math.random()*1.5}if(!target||!target.alive)continue;const dx=target.root.position.x-e.root.position.x,dz=target.root.position.z-e.root.position.z,d=Math.hypot(dx,dz);const dir=new THREE.Vector3(dx,0,dz);if(d>11)moveActor(e,dir,e.speed,dt);else if(d<6){dir.negate();moveActor(e,dir,e.speed*.48,dt)}else e.root.rotation.y=Math.atan2(-dx,-dz);e.body.position.y=Math.sin(gameTime*4+e.phase)*.035;if(d<20&&e.fireTimer<=0){e.fireTimer=1.4+Math.random()*1.7;if(target===player){const hit=Math.random()<Math.max(.18,.66-d*.015);if(hit)playerDamage(3+Math.random()*4);const a=e.root.position.clone().add(new THREE.Vector3(0,1.5,0)),b=player.root.position.clone().add(new THREE.Vector3(0,1.4,0));makeTracer(a,b,0xffa78c)}else if(target.health>0){target.health-=10;if(target.health<=0){target.alive=false;scene.remove(target.root);updateAlive();if(Math.random()<.45)pickup(Math.random()<.5?'med':'weapon',target.root.position.x,target.root.position.z,weapons[Math.floor(Math.random()*weapons.length)])}}} }updateAlive()}
