@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{--cyan:#62f1ff;--lime:#c8ff6b;--panel:rgba(7,22,30,.76);--line:rgba(184,242,235,.16)}
*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#071a24;color:#eef8ed;font-family:'DM Sans',sans-serif;touch-action:none}
canvas{display:block;width:100%;height:100%}
#game{position:fixed;inset:0}
.hud{position:absolute;inset:0;pointer-events:none;display:none}
.topbar{position:absolute;top:max(18px,env(safe-area-inset-top));left:24px;right:24px;display:flex;align-items:flex-start;justify-content:space-between}
.brand{font:900 19px 'Barlow Condensed',sans-serif;letter-spacing:2.5px;text-shadow:0 2px 12px #000}
.brand small{display:block;color:#a6c1bd;font:700 9px 'DM Sans';letter-spacing:2.4px;margin-top:3px}
.stats{display:flex;gap:8px}
.pill{min-width:88px;padding:9px 13px;background:var(--panel);border:1px solid var(--line);border-radius:11px;backdrop-filter:blur(12px);text-align:center;box-shadow:0 8px 26px #00101555}
.pill strong{display:block;font:800 21px 'Barlow Condensed';line-height:1}
.pill span{font-size:8px;letter-spacing:1.6px;color:#a5c1bd;font-weight:800}
.zone-pill strong{color:var(--cyan)}
.kill-pill strong{color:var(--lime)}
.health-wrap{position:absolute;left:25px;bottom:26px;width:220px}
.health-label{font-size:9px;letter-spacing:1.8px;font-weight:800;color:#e3f4eb;display:flex;justify-content:space-between;margin-bottom:7px}
.bar{height:8px;border-radius:20px;background:#10262d;border:1px solid #ffffff25;overflow:hidden}
.bar i{display:block;height:100%;width:100%;background:linear-gradient(90deg,#9bff75,#e2ff82);border-radius:20px;transition:width .2s}
.ammo{position:absolute;right:28px;bottom:27px;text-align:right;font:800 24px 'Barlow Condensed';text-shadow:0 2px 10px #000}
.ammo small{display:block;font:800 9px 'DM Sans';letter-spacing:2px;color:#c3d6cf}
.toast{position:absolute;top:24%;left:50%;transform:translate(-50%,-10px);background:#061a21d9;border:1px solid #71f6fa88;border-radius:30px;padding:10px 19px;font-size:12px;font-weight:700;letter-spacing:.3px;opacity:0;transition:.3s;white-space:nowrap}
.toast.show{opacity:1;transform:translate(-50%,0)}
.crosshair{position:absolute;left:50%;top:50%;width:17px;height:17px;transform:translate(-50%,-50%);opacity:.82}
.crosshair:before,.crosshair:after{content:'';position:absolute;background:#d9ffff;box-shadow:0 0 7px #48eeff}
.crosshair:before{width:2px;height:16px;left:7px;top:0}
.crosshair:after{height:2px;width:16px;top:7px;left:0}
.zone-warning{position:absolute;left:50%;top:17%;transform:translateX(-50%);color:#89f4ff;font-size:11px;font-weight:800;letter-spacing:2px;text-shadow:0 0 12px #12cfff;display:none}
.zone-warning.show{display:block}
.map{position:absolute;top:83px;right:26px;width:108px;height:108px;border-radius:50%;overflow:hidden;border:1px solid #b1f5ed66;background:#07232bd9;box-shadow:0 6px 25px #00101466}
.map canvas{width:100%;height:100%}
.maplabel{position:absolute;right:37px;top:196px;font-size:8px;letter-spacing:1.5px;color:#c9e6df;font-weight:800}
.mobile-controls{display:none}
.stick-area{position:absolute;left:18px;bottom:76px;width:132px;height:132px;border-radius:50%;background:#c9fff00c;border:1px solid #dbfff033;pointer-events:auto;touch-action:none}
.stick{position:absolute;left:50%;top:50%;width:52px;height:52px;transform:translate(-50%,-50%);border-radius:50%;background:#b4ffed25;border:1px solid #d5fff088;box-shadow:0 0 20px #6bffdf20}
.touch-buttons{position:absolute;right:20px;bottom:70px;display:flex;align-items:end;gap:12px;pointer-events:auto}
.touch-btn{border:1px solid #d9fff055;background:#08252bcc;color:white;width:66px;height:66px;border-radius:50%;font:800 10px 'DM Sans';letter-spacing:1px;backdrop-filter:blur(8px);touch-action:none}
.touch-btn.fire{width:82px;height:82px;background:#4bcadb50;border-color:#76efffa6;box-shadow:0 0 25px #44deef35}
.touch-btn.run{width:54px;height:54px;color:#d7ff8b}
.touch-btn.active{background:#bcff7955}
.overlay{position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,#06151bd9 0%,#06151b77 49%,#06151b2a 100%);z-index:5}
.card{width:min(490px,calc(100% - 38px));padding:36px 38px;border:1px solid #ffffff22;background:linear-gradient(145deg,#102b34eF,#071a22ed);border-radius:22px;box-shadow:0 30px 90px #0008;backdrop-filter:blur(15px);position:relative;overflow:hidden}
.card:after{content:'';position:absolute;width:220px;height:220px;border-radius:50%;right:-100px;top:-125px;background:#3de9e927;filter:blur(22px)}
.eyebrow{font-size:9px;letter-spacing:3px;color:var(--cyan);font-weight:800;margin-bottom:12px}
.card h1{font:900 clamp(43px,8vw,64px)/.85 'Barlow Condensed';letter-spacing:1px;margin:0;text-transform:uppercase}
.card h1 em{font-style:normal;color:var(--lime)}
.card p{color:#bfd1cc;font-size:13px;line-height:1.6;margin:19px 0 20px;max-width:380px}
.facts{display:flex;gap:10px;margin-bottom:24px}
.fact{border:1px solid #ffffff18;background:#ffffff08;padding:10px 13px;border-radius:10px;font-size:9px;letter-spacing:1px;color:#b5cbc5;font-weight:800}
.fact b{color:#f2ffea;font-size:13px;display:block;margin-bottom:3px}
.cta{width:100%;height:51px;border:0;border-radius:10px;background:linear-gradient(100deg,#baff6c,#d7ff9a);color:#12241a;font:900 12px 'DM Sans';letter-spacing:2px;box-shadow:0 8px 25px #afff6d22;cursor:pointer;transition:transform .15s}
.cta:hover{transform:translateY(-2px)}
.hint{margin-top:13px!important;font-size:10px!important;color:#89a49e!important;text-align:center}
.end-card{text-align:center}
.end-card h1{line-height:.95}
.end-card .cta{margin-top:6px}
.hide{display:none!important}
.scanlines{position:fixed;inset:0;pointer-events:none;z-index:2;opacity:.1;background:repeating-linear-gradient(0deg,transparent 0px,transparent 3px,#c6ffff 4px);mix-blend-mode:soft-light}
@media(max-width:700px){.topbar{left:15px;right:15px;top:max(12px,env(safe-area-inset-top))}
.brand{font-size:16px}
.brand small{font-size:7px}
.pill{min-width:63px;padding:7px 8px}
.pill strong{font-size:17px}
.pill span{font-size:7px}
.map{width:83px;height:83px;top:98px;right:15px}
.maplabel{top:184px;right:20px;font-size:7px}
.health-wrap{left:15px;bottom:20px;width:150px}
.ammo{right:15px;bottom:20px;font-size:21px}
.mobile-controls{display:block}
.crosshair{display:none}
.health-wrap{bottom:22px}
.toast{top:25%;font-size:11px}
.card{padding:30px 25px}
.facts{gap:6px}
.fact{padding:8px 10px;font-size:8px}
.fact b{font-size:12px}
}
@media(orientation:landscape) and (max-height:500px){.health-wrap{bottom:12px}
.ammo{bottom:12px}
.stick-area{width:102px;height:102px;bottom:45px}
.stick{width:42px;height:42px}
.touch-controls{bottom:40px}
.touch-buttons{bottom:38px}
.map{width:75px;height:75px;top:64px}
.maplabel{top:142px}
.pill{padding:6px 10px}
}
}

