 function fireShot(){if(fireCooldown>0||!started||ended)return;fireCooldown=weapon.rate;const target=nearestTarget(38);const start=player.root.localToWorld(new THREE.Vector3(.35,1.52,-.65));if(target){const end=target.root.position.clone().add(new THREE.Vector3(0,1.45,0));makeTracer(start,end,0xb7ffe0);target.health-=weapon.damage;if(target.health<=0){target.alive=false;scene.remove(target.root);kills++;$('#kills').textContent=String(kills).padStart(2,'0');if(Math.random()<.58)pickup(Math.random()<.45?'med':'weapon',target.root.position.x,target.root.position.z,weapons[Math.floor(Math.random()*weapons.length)]);showToast(`${target.name.toUpperCase()} ELIMINATED`)}else{target.root.userData.hitFlash=.14}}else{const dir=new THREE.Vector3(-Math.sin(player.root.rotation.y),.04,-Math.cos(player.root.rotation.y));makeTracer(start,start.clone().add(dir.multiplyScalar(24)),0xc5fff2)}}
 function updateAlive(){const n=enemies.filter(e=>e.alive).length+1;$('#alive').textContent=String(n)}
 function playerDamage(amount){if(ended)return;health=Math.max(0,health-amount);$('#healthNum').textContent=Math.ceil(health);$('#healthBar').style.width=health+'%';if(health<=0)finish(false)}
